contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(bytes calldata encodedParameters, address ownedBy) public {
        address beforeRoundImpl = c.roundImplementation(); if (__ESBMC_reverted()) return;

        bool reverted;
        address clone;

        address created = c.create(encodedParameters, ownedBy); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            clone = created;
            reverted = false;
        }

        assert(reverted || c.roundImplementation() == beforeRoundImpl);
    }
}

